mapper.select:
SELECT EXISTS (
    SELECT 1 FROM grupo_ingrediente WHERE NOMBRE = #{nombre}
    AND ID <> #{exceptoId}
)

mapper.update:
UPDATE grupo_ingrediente
SET NOMBRE = #{nombre}, RACIONES_SEMANA = #{racionesSemana}, BASICO = #{basico}
WHERE ID = #{id}

UPDATE ingrediente_receta d
JOIN ingrediente_receta o ON o.RECETA = d.RECETA AND o.INGREDIENTE = #{origen}
SET d.CANTIDAD = LEFT(CONCAT(d.CANTIDAD, ' + ', o.CANTIDAD), 100)
WHERE d.INGREDIENTE = #{destino}

mapper.delete:
DELETE o FROM ingrediente_receta o
JOIN ingrediente_receta d ON d.RECETA = o.RECETA AND d.INGREDIENTE = #{destino}
WHERE o.INGREDIENTE = #{origen}

mapper.select:
SELECT ID, NOMBRE, ENERGIA_KJ, GRASAS, GRASAS_SATURADAS, HIDRATOS, FIBRA, PROTEINAS, SODIO_MG FROM alimento_bedca
NOMBRE LIKE #{palabra} ESCAPE '\\'
ORDER BY (NOMBRE LIKE #{prefijo} ESCAPE '\\') DESC, NOMBRE, ID LIMIT #{limite}
